114	    fn emit_with_island(&mut self, inst: Inst, needed_space: u32) {
115	        if self.buffer.island_needed(needed_space) {
116	            let label = self.buffer.get_label();
117	            let jmp = Inst::Jump {
118	                dest: BranchTarget::Label(label),
119	            };
120	            jmp.emit(&mut self.buffer, &self.emit_info, &mut self.emit_state);
121	            self.buffer
122	                .emit_island(needed_space, self.emit_state.ctrl_plane_mut());
123	            self.buffer
124	                .bind_label(label, self.emit_state.ctrl_plane_mut());
125	        }
126	        inst.emit(&mut self.buffer, &self.emit_info, &mut self.emit_state);
127	    }
